<script setup lang="ts">
import {computed,ref,watch,nextTick,onMounted,onBeforeUnmount,onUpdated} from 'vue';
import {mdiPlus,mdiArrowLeft,mdiClose,mdiMagnify} from '@mdi/js';
import type {Database,RequirementsSet,RequirementVersion,InstallationLocation,System,InventoryPC} from '../shared/types';
import {locationPath,installationPCs,installationParts} from '../shared/installations';
import {checkInstalledPC} from '../shared/inventory';
import EngineeringEditor from './EngineeringEditor.vue';
import SoftwareEditor from './SoftwareEditor.vue';
const props=defineProps<{db:Database;revision:string}>();
const emit=defineEmits<{reload:[];notify:[message:string];editPc:[pc:InventoryPC]}>();
const tab=ref('locations'),search=ref(''),locationId=ref(''),busy=ref(false),error=ref('');
const requirementsDraft=ref<RequirementsSet|null>(null),versionDraft=ref<RequirementVersion|null>(null),locationDraft=ref<InstallationLocation|null>(null),assignment=ref<{pcId:string;locationId:string}|null>(null);
const openers=new Map<string,HTMLElement>();
const originals=new Map<string,string>(),revisions=new Map<string,string>();
const dialogs={requirementsDraft,locationDraft,assignment};
for(const [name,draft] of Object.entries(dialogs))watch(draft,value=>{if(value){if(document.activeElement instanceof HTMLElement)openers.set(name,document.activeElement);originals.set(name,JSON.stringify(value));revisions.set(name,props.revision);}else{originals.delete(name);revisions.delete(name);nextTick(()=>{const opener=openers.get(name);if(opener?.isConnected)opener.focus();else document.getElementById('main-content')?.focus();openers.delete(name);});}},{flush:'sync'});
const versionOriginal=ref('');
const dirty=computed(()=>Object.entries(dialogs).some(([name,draft])=>draft.value&&JSON.stringify(draft.value)!==originals.get(name))||!!versionDraft.value&&JSON.stringify(versionDraft.value)!==versionOriginal.value);
function close(name:keyof typeof dialogs){if(dirty.value&&!window.confirm('Discard unsaved installation changes?'))return;dialogs[name].value=null;if(name==='requirementsDraft')versionDraft.value=null;error.value='';}
function confirmDiscard(){if(dirty.value&&!window.confirm('Discard unsaved installation changes?'))return false;requirementsDraft.value=null;versionDraft.value=null;locationDraft.value=null;assignment.value=null;return true;}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue='';}}
function labelTableScrollRegions(){for(const wrapper of Array.from(document.querySelectorAll<HTMLElement>('.installations-workspace .v-table__wrapper'))){const name=wrapper.querySelector('caption')?.textContent?.trim()||'Installation records';wrapper.setAttribute('tabindex','0');wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label',`${name}; scroll to view all columns`);}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);labelTableScrollRegions();});onUpdated(labelTableScrollRegions);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
defineExpose({confirmDiscard,hasUnsavedChanges:()=>dirty.value});
const selectedLocation=computed(()=>props.db.installationLocations.find(l=>l.id===locationId.value));
const locations=computed(()=>props.db.installationLocations.filter(l=>`${locationPath(l.id,props.db)} ${l.notes}`.toLowerCase().includes(search.value.toLowerCase())));
const requirementSets=computed(()=>props.db.requirementsSets.filter(s=>`${s.name} ${s.description}`.toLowerCase().includes(search.value.toLowerCase())));
const requirementLabel=(id:string,revision:number)=>{const set=props.db.requirementsSets.find(s=>s.id===id);return set?`${set.name} · revision ${revision}`:'No requirements linked';};
const attachedPCs=computed(()=>selectedLocation.value?installationPCs(selectedLocation.value.id,props.db,true):[]);
const pcReports=computed(()=>Object.fromEntries(attachedPCs.value.map(pc=>[pc.id,checkInstalledPC(pc,props.db)])));
const locatedParts=computed(()=>selectedLocation.value?installationParts(selectedLocation.value.id,props.db,true):[]);
const requirementChoices=computed(()=>[{title:'No requirements linked',value:''},...props.db.requirementsSets.filter(s=>s.versions.length).map(s=>({title:s.name,value:s.id}))]);
function versionChoices(setId:string){return props.db.requirementsSets.find(s=>s.id===setId)?.versions.map(v=>({title:`Revision ${v.revision} · ${v.name}`,value:v.revision}))||[];}
function selectSet(location:InstallationLocation){location.requirementRevision=props.db.requirementsSets.find(s=>s.id===location.requirementSetId)?.versions.at(-1)?.revision||0;delete location.requirementSnapshot;}
function editRequirements(set?:RequirementsSet){requirementsDraft.value=set?structuredClone(JSON.parse(JSON.stringify(set))):{id:crypto.randomUUID(),name:'',description:'',versions:[]};const last=requirementsDraft.value!.versions.at(-1);versionDraft.value=last?{...JSON.parse(JSON.stringify(last)),revision:last.revision+1,at:new Date().toISOString()}:{revision:1,at:new Date().toISOString(),name:'',description:'',connections:[],constraints:{},software:{}};versionOriginal.value=JSON.stringify(versionDraft.value);error.value='';}
function editLocation(location?:InstallationLocation){locationDraft.value=location?structuredClone(JSON.parse(JSON.stringify(location))):{id:crypto.randomUUID(),name:'',kind:'Bench',parentId:'',requirementSetId:'',requirementRevision:0,targetConfigurationId:'',notes:''};error.value='';}
const requirementSystem=computed<System|undefined>(()=>versionDraft.value?{id:requirementsDraft.value!.id,name:versionDraft.value.name,description:versionDraft.value.description,location:'',connections:versionDraft.value.connections}:undefined);
function addRequired(){if(versionDraft.value)((versionDraft.value.constraints??={}).requiredComponents??=[]).push({componentId:'',quantity:1});}
function addConnection(){versionDraft.value?.connections.push({id:crypto.randomUUID(),name:'',usbA:0,usbC:0,ethernet:0,notes:''});}
function optionalNumber(key:'minMemoryGb'|'minDataGb'|'minBootGb'|'minScientificCards',value:unknown){if(!versionDraft.value)return;const constraints=versionDraft.value.constraints??={};if(value===''||value==null)delete constraints[key];else constraints[key]=Number(value);}
async function save<T extends {id:string}>(collection:string,record:T,dialog:keyof typeof dialogs){busy.value=true;error.value='';try{const response=await fetch(`/api/${collection}/${record.id}`,{method:'PUT',headers:{'Content-Type':'application/json','If-Match':revisions.get(dialog)||props.revision},body:JSON.stringify(record)});const body=await response.json();if(!response.ok)throw Error(body.error||'Save failed');emit('reload');return true;}catch(e){error.value=String(e);return false;}finally{busy.value=false;}}
async function publishRequirements(){if(!requirementsDraft.value||!versionDraft.value)return;versionDraft.value.at=new Date().toISOString();const set={...requirementsDraft.value,versions:[...requirementsDraft.value.versions,{...versionDraft.value,name:versionDraft.value.name||requirementsDraft.value.name}]};if(await save('requirementsSets',set,'requirementsDraft')){requirementsDraft.value=null;versionDraft.value=null;emit('notify','Requirements revision published. Existing configurations and installations keep their pinned revisions.');}}
async function saveLocation(){if(locationDraft.value&&await save('installationLocations',locationDraft.value,'locationDraft')){locationId.value=locationDraft.value.id;locationDraft.value=null;emit('notify','Installation location saved.');}}
async function assignPC(){const pc=props.db.pcs.find(p=>p.id===assignment.value?.pcId);if(!pc||!assignment.value)return;if(await save('pcs',{...pc,installationLocationId:assignment.value.locationId},'assignment')){assignment.value=null;emit('notify','PC location assignment recorded. Installed parts follow this PC.');}}
function parentChoices(){const excluded=new Set<string>(locationDraft.value?[locationDraft.value.id]:[]);let changed=true;while(changed){changed=false;for(const location of props.db.installationLocations)if(excluded.has(location.parentId)&&!excluded.has(location.id)){excluded.add(location.id);changed=true;}}return [{title:'Top-level location',value:''},...props.db.installationLocations.filter(l=>!excluded.has(l.id)).map(l=>({title:locationPath(l.id,props.db),value:l.id}))];}
const componentName=(id:string)=>props.db.components.find(c=>c.id===id)?.name||id;
function back(){locationId.value='';}
</script>
<template>
 <div class="installations-workspace">
 <div class="page-heading"><div><h1>Installations</h1><p>Publish reusable requirements, plan physical installations, and locate built PCs and their parts.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="tab==='requirements'?editRequirements():editLocation()">{{tab==='requirements'?'Create requirements set':'Add installation location'}}</v-btn></div>
 <v-tabs v-model="tab" aria-label="Installation views" color="primary" class="content-tabs" @update:model-value="locationId=''"><v-tab value="locations">Installation locations</v-tab><v-tab value="requirements">Requirements sets</v-tab></v-tabs>
 <v-text-field v-if="!selectedLocation" v-model="search" label="Search installations or requirements" :prepend-inner-icon="mdiMagnify" class="system-search" />
 <template v-if="tab==='requirements'"><section class="panel table-panel"><v-table><caption class="sr-only">Reusable installation requirements and published revisions</caption><thead><tr><th scope="col">Requirements set</th><th scope="col">Published revisions</th><th scope="col">Latest requirements</th><th scope="col">Action</th></tr></thead><tbody><tr v-for="set in requirementSets" :key="set.id"><td><strong>{{set.name}}</strong><small>{{set.description}}</small></td><td>{{set.versions.length}}</td><td>{{set.versions.at(-1)?.description||'No description'}}</td><td><v-btn variant="text" @click="editRequirements(set)">Publish next revision<span class="sr-only"> for {{set.name}}</span></v-btn></td></tr></tbody></v-table><div v-if="!requirementSets.length" class="empty-state"><h2>No requirements sets yet</h2><p>Create a stable requirements set before linking it to a configuration or an installation location.</p></div></section><section v-for="set in requirementSets" :key="set.id" class="panel build-notes"><h2>{{set.name}} revision history</h2><details v-for="version in [...set.versions].reverse()" :key="version.revision" class="my-4"><summary>Revision {{version.revision}} · {{version.name}} · {{new Date(version.at).toLocaleDateString()}}</summary><p>{{version.description}}</p><pre class="snapshot-json" tabindex="0" role="region" aria-label="Pinned requirements revision details">{{JSON.stringify(version,null,2)}}</pre></details></section></template>
 <template v-else-if="!selectedLocation"><section class="panel table-panel"><v-table><caption class="sr-only">Installation locations, requirements and assigned PCs</caption><thead><tr><th scope="col">Location</th><th scope="col">Type</th><th scope="col">Requirements</th><th scope="col">Assigned PCs including descendants</th><th scope="col">Target configuration</th></tr></thead><tbody><tr v-for="location in locations" :key="location.id"><td><button class="table-name" @click="locationId=location.id">{{locationPath(location.id,db)}}</button></td><td>{{location.kind}}</td><td>{{requirementLabel(location.requirementSetId,location.requirementRevision)}}</td><td>{{installationPCs(location.id,db,true).length}}</td><td>{{db.configurations.find(c=>c.id===location.targetConfigurationId)?.name||'Unspecified'}}</td></tr></tbody></v-table><div v-if="!locations.length" class="empty-state"><h2>No installation locations yet</h2><p>Start with a site, room, bench, or equipment system. Parent locations group the PCs and parts in their descendants.</p></div></section></template>
 <template v-else><div class="detail-back"><button @click="back"><v-icon :icon="mdiArrowLeft" aria-hidden="true" />All installation locations</button></div><section class="panel build-notes"><div class="section-head"><div><h2>{{locationPath(selectedLocation.id,db)}}</h2><p>{{selectedLocation.notes}}</p></div><div class="heading-actions"><v-btn variant="outlined" @click="editLocation(selectedLocation)">Edit installation</v-btn><v-btn v-if="['Bench','System'].includes(selectedLocation.kind)" color="primary" @click="assignment={pcId:'',locationId:selectedLocation.id}">Assign PC</v-btn></div></div><p>{{requirementLabel(selectedLocation.requirementSetId,selectedLocation.requirementRevision)}}</p><details v-if="selectedLocation.requirementSnapshot" class="mt-4"><summary>Pinned requirements</summary><pre class="snapshot-json" tabindex="0" role="region" aria-label="Pinned requirements revision details">{{JSON.stringify(selectedLocation.requirementSnapshot,null,2)}}</pre></details></section>
 <section class="panel build-notes"><h2>Assigned PCs</h2><p class="form-hint">Includes PCs at descendant locations. Reservations remain at their stock location until installed.</p><v-table><caption class="sr-only">PCs assigned within this installation</caption><thead><tr><th scope="col">PC</th><th scope="col">Physical installation</th><th scope="col">Lifecycle</th><th scope="col">Installed compatibility</th><th scope="col">Action</th></tr></thead><tbody><tr v-for="pc in attachedPCs" :key="pc.id"><td>{{pc.name}}<small>{{pc.serial}}</small></td><td>{{locationPath(pc.installationLocationId||'',db)}}</td><td>{{pc.lifecycle||'Planning'}}</td><td><details><summary>{{pcReports[pc.id].status}}</summary><ul class="installation-findings"><li v-for="(finding,i) in pcReports[pc.id].findings.filter(f=>f.severity!=='pass')" :key="i"><strong>{{finding.severity==='error'?'Conflict':'Review'}}: {{finding.title}}</strong><p>{{finding.detail}}</p></li></ul></details></td><td><v-btn variant="text" @click="emit('editPc',pc)">Edit PC<span class="sr-only"> {{pc.name}}</span></v-btn></td></tr></tbody></v-table><p v-if="!attachedPCs.length" class="form-hint">No PCs assigned here.</p></section>
 <section class="panel build-notes"><h2>Installed parts at this location</h2><v-table><caption class="sr-only">Physical components installed in PCs at this location and its descendants</caption><thead><tr><th scope="col">Component</th><th scope="col">Serial / asset / lot</th><th scope="col">Quantity</th><th scope="col">PC</th><th scope="col">Location</th><th scope="col">Placement</th></tr></thead><tbody><tr v-for="row in locatedParts" :key="row.allocation.id"><td>{{componentName(row.stock.componentId)}}</td><td>{{row.stock.serial||row.stock.assetTag||'Unlabelled bulk stock'}}</td><td>{{row.allocation.quantity}}</td><td>{{row.pc.name}}</td><td>{{row.locationPath}}</td><td>{{row.allocation.slotId||row.allocation.targetId||row.allocation.mount}}</td></tr></tbody></v-table><p v-if="!locatedParts.length" class="form-hint">No installed parts recorded in assigned PCs.</p></section></template>
 <v-dialog :model-value="!!requirementsDraft" @keydown.esc.stop.prevent="close('requirementsDraft')" max-width="1000" persistent aria-labelledby="requirements-editor-title"><v-card v-if="requirementsDraft&&versionDraft" class="editor-dialog"><div class="dialog-head"><h2 id="requirements-editor-title">Publish installation requirements</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close requirements editor" @click="close('requirementsDraft')" /></div><div class="dialog-body"><v-alert v-if="error" type="error" role="alert" class="mb-5">{{error}}</v-alert><div class="form-grid"><v-text-field v-model="requirementsDraft.name" label="Requirements set name" required /><v-text-field v-model="versionDraft.name" label="Revision title (defaults to set name)" /></div><v-textarea v-model="requirementsDraft.description" label="Requirements set description" rows="2" /><v-textarea v-model="versionDraft.description" label="Purpose and acceptance requirements for this revision" rows="3" /><p class="form-hint">Revision {{versionDraft.revision}} will be immutable after publication. Existing installations keep their chosen revision.</p><h3>Minimum engineering requirements</h3><div class="form-grid mt-4"><v-text-field :model-value="versionDraft.constraints?.minMemoryGb" label="Minimum RAM (GB)" type="number" min="0" @update:model-value="v=>optionalNumber('minMemoryGb',v)" /><v-text-field :model-value="versionDraft.constraints?.minDataGb" label="Minimum usable data storage (GB)" type="number" min="0" @update:model-value="v=>optionalNumber('minDataGb',v)" /><v-text-field :model-value="versionDraft.constraints?.minBootGb" label="Minimum boot storage (GB)" type="number" min="0" @update:model-value="v=>optionalNumber('minBootGb',v)" /><v-text-field :model-value="versionDraft.constraints?.minScientificCards" label="Minimum scientific acquisition cards" type="number" min="0" @update:model-value="v=>optionalNumber('minScientificCards',v)" /></div><div class="spec-heading"><h3>Required component types</h3><v-btn variant="outlined" @click="addRequired">Add component requirement</v-btn></div><div v-for="(required,i) in versionDraft.constraints?.requiredComponents" :key="i" class="form-grid"><v-select v-model="required.componentId" label="Required component type" :items="db.components.map(c=>({title:c.name,value:c.id}))" /><v-text-field v-model.number="required.quantity" label="Required quantity" type="number" min="1" /><v-btn variant="text" color="error" @click="versionDraft.constraints?.requiredComponents?.splice(i,1)">Remove component requirement</v-btn></div><div class="spec-heading"><h3>Equipment connections</h3><v-btn variant="outlined" @click="addConnection">Add equipment</v-btn></div><div v-for="(connection,i) in versionDraft.connections" :key="connection.id" class="connection-form"><div class="form-grid"><v-text-field v-model="connection.name" label="Equipment name" /><v-text-field v-model.number="connection.usbA" label="Dedicated USB-A connections" type="number" min="0" /><v-text-field v-model.number="connection.usbC" label="Dedicated USB-C connections" type="number" min="0" /><v-text-field v-model.number="connection.ethernet" label="Dedicated Ethernet connections" type="number" min="0" /></div><v-textarea v-model="connection.notes" label="Equipment connection notes" rows="2" /><v-btn variant="text" color="error" @click="versionDraft.connections.splice(i,1)">Remove equipment<span class="sr-only"> {{connection.name}}</span></v-btn></div><EngineeringEditor v-if="requirementSystem" :system="requirementSystem" :db="db" /><SoftwareEditor v-if="versionDraft.software" :software="versionDraft.software" :components="db.components" /><v-btn v-else variant="outlined" @click="versionDraft.software={}">Add software requirements</v-btn><div class="spec-heading"><h3>Storage requirements</h3><v-btn v-if="!versionDraft.storage" variant="outlined" @click="versionDraft.storage={raid:'none',bootMirror:false}">Specify redundancy</v-btn></div><div v-if="versionDraft.storage" class="form-grid"><v-select v-model="versionDraft.storage.raid" label="Required default data redundancy" :items="['none','mirror','raid5','raid6','raid10']" /><v-switch v-model="versionDraft.storage.bootMirror" label="Require boot mirror" color="primary" /><v-btn variant="text" @click="delete versionDraft.storage">Remove storage requirements</v-btn></div></div><div class="dialog-footer"><v-btn variant="text" @click="close('requirementsDraft')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!requirementsDraft.name.trim()" @click="publishRequirements">Publish revision {{versionDraft.revision}}</v-btn></div></v-card></v-dialog>
 <v-dialog :model-value="!!locationDraft" @keydown.esc.stop.prevent="close('locationDraft')" max-width="760" persistent aria-labelledby="installation-editor-title"><v-card v-if="locationDraft" class="editor-dialog"><div class="dialog-head"><h2 id="installation-editor-title">{{locationDraft.name||'New installation location'}}</h2><v-btn :icon="mdiClose" aria-label="Close installation editor" variant="text" @click="close('locationDraft')" /></div><div class="dialog-body"><v-alert v-if="error" type="error" role="alert" class="mb-5">{{error}}</v-alert><div class="form-grid"><v-text-field v-model="locationDraft.name" label="Installation location name" required /><v-select v-model="locationDraft.kind" label="Location type" :items="['Site','Room','Bench','System']" /><v-select v-model="locationDraft.parentId" label="Parent location" :items="parentChoices()" /><v-select v-model="locationDraft.targetConfigurationId" label="Target PC configuration" :items="[{title:'Unspecified',value:''},...db.configurations.map(c=>({title:c.name,value:c.id}))]" /><v-select v-model="locationDraft.requirementSetId" label="Installation requirements set" :items="requirementChoices" @update:model-value="selectSet(locationDraft!)" /><v-select v-if="locationDraft.requirementSetId" v-model="locationDraft.requirementRevision" label="Pinned requirements revision" :items="versionChoices(locationDraft.requirementSetId)" /></div><v-textarea v-model="locationDraft.notes" label="Installation and access notes" rows="3" /></div><div class="dialog-footer"><v-btn variant="text" @click="close('locationDraft')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!locationDraft.name.trim()" @click="saveLocation">Save installation</v-btn></div></v-card></v-dialog>
 <v-dialog :model-value="!!assignment" @keydown.esc.stop.prevent="close('assignment')" max-width="600" persistent aria-labelledby="assignment-editor-title"><v-card v-if="assignment" class="editor-dialog"><div class="dialog-head"><h2 id="assignment-editor-title">Assign a PC to an installation</h2><v-btn :icon="mdiClose" variant="text" aria-label="Close PC assignment" @click="close('assignment')" /></div><div class="dialog-body"><v-alert v-if="error" type="error" role="alert" class="mb-5">{{error}}</v-alert><v-select v-model="assignment.pcId" label="Built PC" :items="db.pcs.filter(p=>p.lifecycle!=='Retired').map(p=>({title:`${p.name} · ${p.lifecycle||'Planning'}`,value:p.id}))" /><v-select v-model="assignment.locationId" label="Physical installation location" :items="db.installationLocations.filter(l=>['Bench','System'].includes(l.kind)).map(l=>({title:locationPath(l.id,db),value:l.id}))" /><p class="form-hint">This records physical placement. Installed component whereabouts follow the PC; its build plan and commissioning records remain unchanged. Review the installed compatibility against the pinned location requirements.</p></div><div class="dialog-footer"><v-btn variant="text" @click="close('assignment')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!assignment.pcId||!assignment.locationId" @click="assignPC">Assign PC</v-btn></div></v-card></v-dialog>
 </div>
</template>
